def format_authors(authors):
    if isinstance(authors, str):
        return authors
    formatted = []
    for a in authors:
        a = a.strip().rstrip('.')
        parts = a.split()
        if len(parts) >= 2:
            last = parts[0]
            first = ' '.join(parts[1:])
            formatted.append(f"{last}, {first}")
        else:
            formatted.append(a)
    return ' and '.join(formatted)
